 async function patchStock(data){if(data._lookbackPatch)return data;await patchIndex();if(!patchCache.has(data.code))patchCache.set(data.code,(async()=>{const r=await fetch('single_stock_patch/stocks/'+data.code+'.json.gz');if(!r.ok)throw Error();const bytes=new Uint8Array(await r.arrayBuffer());const patch=bytes[0]===0x1f&&bytes[1]===0x8b?await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).json():JSON.parse(new TextDecoder().decode(bytes));if(patch.code!==data.code||!Array.isArray(patch.calendar)||!Array.isArray(patch.prices)||!patch.nodes)throw Error();return patch;})().catch(e=>{patchCache.delete(data.code);throw e;}));const p=await patchCache.get(data.code);return {...data,calendar:p.calendar,prices:p.prices,nodes:data.nodes.map(n=>({...n,anchors_by_lookback:p.nodes[n.id]?.anchors_by_lookback})),_lookbackPatch:true};}
 async function refreshPrior(){if(!current)return;const original=current,ticket=request,selected=visibleNodes[+el('stock-event').value]?.id;el('stock-chart').textContent='正在匹配所选此前观察期…';el('stock-reference-info').textContent='';el('stock-to-cell').disabled=true;try{const updated=await patchStock(original);if(ticket!==request||current!==original)return;const latestSelected=visibleNodes[+el('stock-event').value]?.id;current=updated;buildNodes(latestSelected);}catch{if(ticket!==request||current!==original)return;if(priorDays()===60)buildNodes(selected);else{el('stock-chart').textContent='该股票此前观察期匹配数据未能加载，请重新查询股票或切换观察期；不显示60日旧参考。';el('stock-reference-info').textContent='';}}}
 window.addEventListener('prior-changed',()=>{renderQueryCoverage();refreshPrior();});
 window.addEventListener('prior-loading',()=>{el('stock-to-cell').disabled=true;});
 function tab(stock){el('stock-panel').hidden=!stock;el('matrix-panel').hidden=stock;el('tab-stock').setAttribute('aria-pressed',stock);el('tab-matrix').setAttribute('aria-pressed',!stock);if(stock)loadIndex();}
 el('tab-stock').onclick=()=>tab(true);el('tab-matrix').onclick=()=>tab(false);
 async function loadIndex(){
  if(index)return index;if(indexPromise)return indexPromise;
  el('stock-status').textContent='正在读取股票目录…';
  indexPromise=fetch('single_stock/index.json').then(r=>{if(!r.ok)throw Error('目录暂不可用');return r.json();}).then(d=>{
   index=d;el('stock-options').replaceChildren(...d.stocks.map(s=>{const o=document.createElement('option');o.value=s.code;o.label=s.name;return o;}));
   el('stock-status').textContent='可查询'+num(d.stocks.length)+'只股票（数据快照）；输入6位代码或名称，只加载所选股票。';
   el('stock-coverage').textContent=(d.metadata.query_universe?'查询名册：冻结供应商A股名册，当前收录'+num(d.stocks.length)+'只，未独立认证为完整实时交易所名册；名称含退的'+(d.excluded_stocks?.length||0)+'只未纳入。参考研究池仍为1494只，查询范围与研究池不同；可查询不保证有可匹配参考。北交所使用现920代码或名称，不自动替换历史代码。':'查询范围为1494只研究池股票。')+'冻结行情截至'+d.metadata.price_as_of+'；近一年展示'+d.metadata.display_start+'至'+d.metadata.price_as_of+'，不是实时行情；股东公布日采用供应商日期，未逐条核实首次公开时刻。';
   renderQueryCoverage();return d;
  }).catch(()=>{indexPromise=null;el('stock-status').textContent='股票目录未能加载，请稍后重新打开单股视图。';return null;});return indexPromise;
 }
 function renderQueryCoverage(){if(!index)return;const c=index.metadata.coverage;if(!c){el('stock-query-coverage').textContent='可查询不等于每个节点都有可比历史参考。';return;}el('stock-query-coverage').textContent='查询覆盖'+num(c.query_count)+'只，其中采集区间有行情'+num(c.source_price_rows_available_stocks||c.price_available_stocks)+'只；展示近一年内有可用行情'+num(c.display_window_price_available_stocks||c.price_available_stocks)+'只、'+num(c.stocks_with_nodes)+'只有返回节点。此前'+priorDays()+'个市场交易日口径下，仅'+num(c.stocks_with_comparable_nodes_by_lookback[String(priorDays())])+'只在近一年至少有一个可匹配节点（任一起点）。查询覆盖不等于可生成同类参考，更不代表都有可靠预测；仍须逐节点检查间隔、滞后、价格特征和样本数。';}
 function normalizeCode(query){return query.trim().toUpperCase().replace(/^(SH|SZ|BJ)[.\s-]?/,'').replace(/[.\s-]?(SH|SZ|BJ)$/,'');}
 function resolve(query){const code=normalizeCode(query);if(/^\d{6}$/.test(code))return index.stocks.find(s=>s.code===code);return index.stocks.find(s=>s.name===query.trim())||index.stocks.find(s=>(s.code+' '+s.name)===query.trim());}
 el('stock-form').onsubmit=async e=>{
  e.preventDefault();const ticket=++request;const list=await loadIndex();if(!list||ticket!==request)return;const found=resolve(el('stock-query').value);
  current=null;el('stock-result').hidden=true;
  if(!found){const q=el('stock-query').value,excluded=index.excluded_stocks?.find(s=>s.code===normalizeCode(q)||s.name===q.trim());el('stock-status').textContent=excluded?(excluded.code+' '+excluded.name+'：本次查询范围未纳入供应商名称含“退”的股票；这不是实时退市状态认证。'):'当前冻结查询名册未收录该代码或名称。请输入完整6位代码（保留前导0）或准确名称；北交所请使用现920代码，不自动转换历史代码。';return;}
  el('stock-status').textContent='正在加载'+found.code+' '+found.name+'…';
  try{const file=found.file;if(!new RegExp('^stocks/'+found.code+'\\.json(?:\\.gz)?$').test(file))throw Error();const r=await fetch('single_stock/'+file);if(!r.ok)throw Error();let data;const bytes=new Uint8Array(await r.arrayBuffer());if(bytes[0]===0x1f&&bytes[1]===0x8b){if(typeof DecompressionStream==='undefined')throw Error('unsupported_gzip');data=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).json();}else data=JSON.parse(new TextDecoder().decode(bytes));if(ticket!==request)return;if(data.code!==found.code||!Array.isArray(data.prices)||!Array.isArray(data.nodes))throw Error();current={...data,_entry:found};el('stock-data-status').textContent=stockDataStatus(found,data);el('stock-title').textContent=data.code+' '+data.name;el('stock-result').hidden=false;el('stock-status').textContent='已加载冻结数据；切换日期节点查看对应历史参考。';if(priorDays()===60)buildNodes();else await refreshPrior();}
  catch(error){if(ticket===request)el('stock-status').textContent=error.message==='unsupported_gzip'?'当前浏览器不支持股票数据解压，请使用更新版本的浏览器。':'该股票数据未能加载，请重试；不会使用其他股票或模拟数据替代。';}
 };
 const fmtCount=v=>v==null?'无可用数据':num(Number(v));
 function stockDataStatus(entry,data){const member=entry.reference_pool_member;const scope=member===false?'不属于1494只参考研究池，但可按相同条件匹配历史参考。':member===true?'属于1494只参考研究池。':'';const holders={missing_A_count:'来源未提供A股股东户数，不能用股东总户数替代。',raw_missing:'供应商资料有来源缺口，未返回可展示的近期节点；不代表公司没有披露。',no_recent_disclosure:'本次来源没有返回近期股东节点；不代表公司没有披露。',no_recent_nodes:'本次来源没有返回近期股东节点；不代表公司没有披露。',date_anomaly_only:'返回的节点存在日期异常，可查看但不作可比参考。',noncanonical_only:'返回节点均不符合标准事件口径，可查看不可强行匹配。'};const hasPrice=data.prices.some(p=>p.date>=index.metadata.display_start&&p.date<=index.metadata.display_end&&Number.isFinite(p.close));const priceNote=['empty_no_price','no_prices_in_requested_window'].includes(entry.price_status)?'来源未返回请求区间内行情。':['error','failed','parse_error','request_error','fetch_error'].includes(entry.price_status)?'本次行情采集或解析未成功，不能据此判断股票没有交易。':'';return scope+priceNote+(holders[entry.holder_status]||'节点能展示不等于符合研究可比条件。')+(!hasPrice?(['ok','ok_reused_frozen'].includes(entry.price_status)?'来源采集成功，但展示一年内没有可用行情'+(entry.recorded_last_price_date?'（来源最后有效行情日'+entry.recorded_last_price_date+'）':'')+'；不推断停牌、退市或上市时间，也不生成模拟走势。':'近一年没有可绘制的有效行情；仅表示本次冻结来源的可用情况，不生成模拟走势。'):'')+' 参考始终使用原1494股全历史分组，不是为此股票重新训练或当时可得预测。';}
 const mode=()=>el('stock-anchor').value;
 const nodeDate=(n,a=mode())=>a==='public_nextopen'?n.notice:n.endpoint;
 function buildNodes(selectedId){
  if(!current)return;const m=index.metadata;
  visibleNodes=current.nodes.filter(n=>nodeDate(n)>=m.display_start&&nodeDate(n)<=m.display_end).sort((a,b)=>nodeDate(a).localeCompare(nodeDate(b))||String(a.id).localeCompare(String(b.id)));
  el('stock-event').replaceChildren(...visibleNodes.map((n,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=nodeDate(n)+(mode()==='public_nextopen'?' · 统计'+n.endpoint:' · 公布'+n.notice)+' · 户数'+(n.holder_num==null?'来源缺A股户数':Number(n.holder_num).toLocaleString('zh-CN'))+(match(n)?.eligible?'':' · 不可匹配');return o;}));
  let first=visibleNodes.length-1;for(let i=visibleNodes.length-1;i>=0;i--)if(match(visibleNodes[i])?.eligible){first=i;break;}const retained=selectedId?visibleNodes.findIndex(n=>n.id===selectedId):-1;el('stock-event').value=String(retained>=0?retained:Math.max(0,first));draw();
 }
 function stepNode(delta){if(el('stock-panel').hidden||!current||!visibleNodes.length)return;const from=+el('stock-event').value,to=Math.min(visibleNodes.length-1,Math.max(0,from+delta));if(to!==from){el('stock-event').value=String(to);draw();}}
 el('stock-prev').onclick=()=>stepNode(-1);el('stock-next').onclick=()=>stepNode(1);
 document.addEventListener('keydown',e=>{if(el('stock-panel').hidden||!current||!visibleNodes.length||e.metaKey||e.ctrlKey||e.altKey||e.shiftKey||!['ArrowLeft','ArrowRight'].includes(e.key))return;const target=e.target;if(target?.closest?.('input,textarea,select,[contenteditable]:not([contenteditable="false"]),[role="textbox"]'))return;e.preventDefault();stepNode(e.key==='ArrowLeft'?-1:1);});
 el('stock-anchor').onchange=buildNodes;el('stock-event').onchange=draw;el('stock-band').onchange=draw;
